# Runs the generator, writes icons.json, boards-layout.json, CLICKS.md, glossary.json and runs the self-checks.
import json, os, sys, glob
sys.dont_write_bytecode = True
import gen
for f in glob.glob(os.path.join(gen.ROOT, '*.dc.html')):
    os.remove(f)
import b1, b2, b3, b4, b5, b6, b7, b8, b9
from actions import ACTIONS
from icons import I
HERE = gen.HERE
# ---- layout: rows of related boards, 80 between frames, 120 between rows ----
GAP_X, GAP_Y = 80, 120
layout = {}; y = 0
for r in sorted({b['row'] for b in gen.boards.values()}):
    x = 0; hmax = 0
    for name in gen.order:
        b = gen.boards[name]
        if b['row'] != r: continue
        layout[name] = dict(x=x, y=y, w=b['w'], h=b['h'], title=b['title'])
        x += b['w'] + GAP_X; hmax = max(hmax, b['h'])
    y += hmax + GAP_Y
json.dump(layout, open(os.path.join(HERE, 'boards-layout.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
# ---- icons.json ----
icons = [dict(name=n, meaning=d['meaning'], mirrored_in_rtl=d['mirror'], used_in=sorted(x.replace('.dc.html', '') for x in gen.ICON_USE.get(n, ()))) for n, d in I.items()]
unused = [i['name'] for i in icons if not i['used_in']]
assert not unused, 'icons defined but not used: %s' % unused
json.dump(dict(rule='one icon = one meaning; stroke %s at 24; sizes 16 and 24; mirroring depends on the direction at draw time' % gen.STROKE, icons=icons,
    pictograms=[dict(name='display-mode-' + k, meaning=m, mirrored_in_rtl=False, used_in=['Projection', 'SettingsDisplay', 'SettingsDisplayLight']) for k, m in (('extend', 'displays extended'), ('mirror', 'displays mirrored'), ('first', 'only this device / only one display'), ('second', 'only the second display'))],
    brand=[dict(name='mark', meaning='brand mark = Overview button', mirrored_in_rtl=False, used_in=sorted(x.replace('.dc.html', '') for x in gen.ICON_USE.get('mark', ())))]), open(os.path.join(HERE, 'icons.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
# ---- CLICKS.md ----
out = ['# Click list of the artboards (round 2)', '', 'Generated by `build.py` from the click register of the generator: every `<button>`, `<a>`, `<input>` and slider of every board carries `data-act`; the build fails when an element has none or the action is not defined in `actions.py`.',
       'Ref = section of `docs/DESKTOP-SPEC.md`. **NEW** = not defined there; the text is the proposed definition (collected at the end).', '']
total = 0
for name in gen.order:
    rows = gen.CLICKS[name]; total += len(rows)
    out += ['## %s (%d)' % (name.replace('.dc.html', ''), len(rows)), '', '| # | Element (accessible name) | Action | What it does | Ref |', '|---|---|---|---|---|']
    for i, (label, a) in enumerate(rows, 1):
        out.append('| %d | %s | `%s` | %s | %s |' % (i, label.replace('|', '/'), a, ACTIONS[a][0], ACTIONS[a][1]))
    out.append('')
used = {a for rows in gen.CLICKS.values() for _, a in rows}
assert used == set(ACTIONS), 'actions defined but unused: %s' % sorted(set(ACTIONS) - used)
out += ['## Spec additions needed', '', 'Behaviour the specification does not define yet. Each line is the definition the artboards assume; add it to `docs/DESKTOP-SPEC.md` (section in brackets) or change the board.', '']
SECTION = {'shell': '§5.1', 'apps': '§5.1', 'mobile': '§5.5', 'win': '§5.2', 'desk': '§5.1', 'files': '§9 Files', 'browser': '§9/§11 Browser', 'qs': '§5.1 Quick settings', 'note': '§5.1/§5.3', 'cal': '§5.1', 'overview': '§5.1', 'lock': '§5.3', 'login': '§5.3', 'settings': '§8', 'display': '§8 Display', 'projection': '§8/§5.4', 'drivers': '§8', 'account': '§12.1', 'installer': '§6', 'store': '§7.3', 'phone': '§12.2', 'mesh': '§8 Mesh, §5.5'}
n = 0
for a, (text, ref) in ACTIONS.items():
    if 'NEW' in ref:
        n += 1; out.append('%d. `%s` [%s] – %s' % (n, a, SECTION[a.split('.')[0]], text))
out += ['', 'Further additions that are not a single click:', '',
        '%d. [§3] State tokens: `[state]` (overlays, disabled opacity, scrim, focus-ring role), `size.border`, `size.row_min`, `size.box` in `design/tokens.toml`; boards and toolkit read the same values (section 3, rows "Fokusrahmen" and "Zustände").' % (n + 1),
        '%d. [§4] Icon table: see `ICONS.md` (new and split meanings).' % (n + 2),
        '%d. [§5.1] Sheets of the shell (quick settings, calendar) take the focus when they open, keep it inside (Tab cycles) and return it to their trigger when they close.' % (n + 3),
        '%d. [§5.2] The three title-bar buttons are not Tab stops; keyboard uses the window menu (Alt+Space) and the shortcuts. In Arabic the start position of new windows is mirrored.' % (n + 4),
        '%d. [§8] Row "Main display": the main display shows a badge; every other display shows a button "Make this the main display". There is no "off".' % (n + 5),
        '%d. [§3/§10] Units inside Arabic text are written in Latin (GB, MB, Hz, Gbit/s) as a left-to-right island; technical words are transliterated (واي فاي, بلوتوث), acronyms stay Latin (VPN, USB, HDR, PDF, SIM, QR, TPM, PIN).' % (n + 6),
        '%d. [§3/§5.5] Compact class (phone, 360 wide): status bar 32 high (time at the start, state icons at the end = quick settings), gesture bar = touch target high at the lower edge, app grids in 4 columns, settings and Store as list → page with a Back button at the start, the Store areas as tabs plus a menu, Store rows open the app page (boards Compact*).' % (n + 7), '']
out.insert(4, 'Total: **%d clickable elements on %d boards**, %d distinct actions, %d of them with behaviour newly defined here.' % (total, len(gen.order), len(ACTIONS), n))
open(os.path.join(HERE, 'CLICKS.md'), 'w', encoding='utf-8').write('\n'.join(out))
print('boards: %d, clicks: %d, actions: %d (new: %d), icons: %d' % (len(gen.order), total, len(ACTIONS), n, len(icons)))
# ---- ICONS.md ----
GROUPS = [('Navigation', ['back', 'forward', 'chevron-down', 'home', 'grid', 'search', 'more']), ('Window', ['min', 'max', 'close']), ('Actions', ['plus', 'trash', 'copy', 'download', 'reload', 'eject', 'backspace']),
    ('State', ['check', 'info', 'warning', 'error', 'lock', 'secure', 'shield', 'eye', 'ring', 'block']), ('Connection', ['wifi', 'offline', 'cable', 'cell', 'plane', 'bluetooth', 'vpn', 'mesh', 'cloud', 'network', 'sharing']),
    ('Device', ['volume', 'speaker', 'mic', 'sun', 'moon', 'contrast', 'battery', 'monitor', 'keyboard', 'mouse', 'printer', 'chip', 'video', 'camera-switch', 'screen-share', 'usb', 'disk', 'device']),
    ('Phone', ['phone', 'hangup', 'keypad', 'pause', 'message', 'call-in', 'call-out', 'call-missed', 'qr']),
    ('System', ['gear', 'power', 'user', 'users', 'bell', 'bell-off', 'clock', 'bag', 'folder', 'access', 'spark', 'update', 'shot', 'palette', 'colour', 'dock', 'workspaces', 'apps', 'language', 'backup', 'cells', 'sos']),
    ('Media transport', ['play', 'prev', 'next']), ('Store', ['compass', 'installed', 'package-file']), ('App family', ['browser', 'firefox', 'terminal', 'editor']),
    ('Components', ['office', 'code', 'media', 'mail', 'package', 'windows', 'android', 'server', 'remote']), ('Places in Files', ['place-documents', 'place-downloads', 'place-pictures', 'place-music', 'bin']), ('File kinds', ['kind-folder', 'kind-text', 'kind-sheet', 'kind-image'])]
grouped = [n for _, ns in GROUPS for n in ns]
assert sorted(grouped) == sorted(I), set(I) ^ set(grouped)
md = ['# Icon table – proposal for DESKTOP-SPEC section 4 (round 2)', '', 'Source: `icons.py` (drawings), `icons.json` (name, meaning, mirrored in RTL, where used) – both written by the generator.',
      'Rules kept: one set, stroke %s at 24, two sizes (16, 24), outline. One icon = one meaning, one meaning = one icon.' % gen.STROKE,
      '"Mirrored in RTL" is a property of the icon; the generator mirrors at draw time from the direction of the board (`ic()` in `gen.py`), never in a call. The check `icon mirroring by direction` fails on any other case.', '',
      '## Double meanings of round 1 and how they are resolved', '', '| Round-1 finding | Was | Now |', '|---|---|---|',
      '| D46 `grid` | all apps + settings area Apps + Store Installed + Android | `grid` = all apps only · `apps` = settings area · `installed` = Store · `android` = component |',
      '| D47 `shield` | security + VPN + containers + tracking protection | `shield` = security only · `vpn` = shield with key · `server` = containers and server · `block` = ad and tracker blocking |',
      '| D48 `update` | reload + updates | `reload` = one circular arrow · `update` = arrow up in a circle |',
      '| D49 `star` | Discover + main display | `compass` = Discover · main display = text badge with `check` (no icon of its own); `star` stays reserved for "favourite" and is not drawn yet |',
      '| D50 `file` | text editor + Documents + .docx + .xlsx + Office | `editor` (app) · `place-documents` · `kind-text` · `kind-sheet` · `office` (component) |',
      '| D51 `box` | Linux programs + Store section | `package` = Linux programs only; the Store section is gone (it is part of Discover) · `package-file` = install from a file |',
      '| D52 `window` | settings area + Windows programs | `workspaces` and `dock` = the two settings areas · `windows` = component |',
      '| D53 `globe` | Ultar Browser + Firefox | `browser` · `firefox` |',
      '| D54 `chev` | back/forward + select arrow (rotated) | `back`, `forward` (mirrored by direction) · `chevron-down` = select, own drawing, no rotation |',
      '| D55 `bell` | notifications + do not disturb | `bell` · `bell-off` (crossed) |',
      '| D56 `lock` | locked + secure connection | `lock` · `secure` (lock with check) |',
      '| D57 `trash` | delete + place Trash | `trash` = delete (action) · `bin` = place Trash (bar, dock, Files) |',
      '| D58 `download`, `music`, `image`, `usb` | places and actions | `download` = action · `place-downloads`, `place-music`, `place-pictures` = places · `media` = component · `kind-image` = file kind · `usb` = removable drive (one meaning: the drive, wherever it is shown) |',
      '| section 4 itself: moon = night light **and** dark | two meanings | `moon` = night light · `contrast` = dark theme |',
      '| section 4 itself: person = account, cloud = Ultar account | overlap | `user` = account/person (sign-in, online accounts) · `cloud` = Ultar account and its services · `users` = users of this device |', '',
      '## Decisions on mirroring (R10–R15)', '', '- `back`/`forward`: mirrored; in Arabic "back" points right.', '- `volume`: mirrored (waves point in the direction the slider grows).', '- `kind-text`, `kind-sheet`, `place-documents`, `spark`, `message`, `copy`, `backspace`, `battery`, `cell`, call arrows, `language`, `backup`, `reload`, `sharing`, `users`: mirrored (they have a reading direction).',
      '- Display-mode pictograms: physical picture of two screens, **never** mirrored; the arrow of round 1 is gone (extend = two outlines joined by a line).', '- Media transport, clock-like and symmetric icons, brand mark: never mirrored.', '',
      '## Table', '']
for gname, ns in GROUPS:
    md += ['### ' + gname, '', '| Icon | Meaning | Mirrored in RTL | Used on |', '|---|---|---|---|']
    for n in ns:
        md.append('| `%s` | %s | %s | %s |' % (n, I[n]['meaning'], 'yes' if I[n]['mirror'] else 'no', ', '.join(sorted(x.replace('.dc.html', '') for x in gen.ICON_USE[n]))))
    md.append('')
md += ['### Brand', '', '| Icon | Meaning | Mirrored in RTL | Used on |', '|---|---|---|---|',
       '| `mark` | brand mark = Overview button (two open arcs, stroke %s, colour accent_text; path `M12 3a9 9 0 1 0 9 9` + `M12 8a4 4 0 1 0 4 4`). Drawn by `mark()` in `gen.py`; ultar-ui gets it as `IconId::Mark` ("mark", not mirrored) | no | %s |' % (gen.STROKE, ', '.join(sorted(x.replace('.dc.html', '') for x in gen.ICON_USE['mark']))), '']
md += ['## Named in section 4, not needed on these boards (keep in the table, not drawn yet)', '', 'main menu (three lines), restore (two squares), pen, clipboard, scissors, share/export, import, undo, unlock, eye crossed, microphone crossed, speaker muted, video crossed, calendar sheet, star, pin, cloud variants.', '',
       '## Open', '', '- App icons are monochrome here: the coloured app family of section 4 needs colour tokens per theme (round-1 finding D40/A1). No colour outside `tokens.toml` is used.', '- File and app icons larger than 24 need a size token (`icon_large`); the boards put a 24 icon in a 48 tile instead.', '']
open(os.path.join(HERE, 'ICONS.md'), 'w', encoding='utf-8').write('\n'.join(md))
# ---- catalog proposal: new strings of the round-4 boards (builders move them into the .ftl catalogs) ----
cat = ['# Catalog proposal – new strings of the round-4 boards', '', 'Keys follow `system/core/ultar-i18n/locales/*.ftl`. Builders add them to `ar.ftl` and `en.ftl` (and `de.ftl`); a key that already exists keeps its text.', '',
       '| Key | ar | en |', '|---|---|---|']
cat += ['| `%s` | %s | %s |' % (k, a.replace('|', '/'), e.replace('|', '/')) for k, (a, e) in sorted(b8.STR.items())]
open(os.path.join(HERE, 'CATALOG-PROPOSAL.md'), 'w', encoding='utf-8').write('\n'.join(cat) + '\n')
import check
sys.exit(check.run(layout))
